theorem IsRIntegralPS.add {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) :
    IsRIntegralPS r (F + G)

theorem constantCoeff_toSubringPS_eq_zero {r : ℕ} {F : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hF0 : PowerSeries.constantCoeff F = 0) :
    PowerSeries.constantCoeff hF.toSubringPS = 0

theorem mapTo_congr_proof {r : ℕ} {A : Type*} [CommSemiring A]
    (φ : rIntegralRatSubring r →+* A) {F : PowerSeries ℚ}
    (hF hF' : IsRIntegralPS r F) : hF.mapTo φ = hF'.mapTo φ

theorem IsRIntegralPS.mul {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) :
    IsRIntegralPS r (F * G)

theorem IsRIntegralPS.sub {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) :
    IsRIntegralPS r (F - G)

theorem IsRIntegralPS.subst_X_pow {r k : ℕ} (hk : k ≠ 0) {F : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) :
    IsRIntegralPS r (PowerSeries.subst (PowerSeries.X ^ k) F)

theorem IsRIntegralRat.add {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    IsRIntegralRat r (q₁ + q₂)

theorem exists_eq_natCast_mul_of_toZMod_eq_zero {r : ℕ} {q : ℚ}
    (h : IsRIntegralRat r q) (hz : toZMod q h = 0) :
    ∃ q' : ℚ, IsRIntegralRat r q' ∧ q = (r : ℚ) * q'

theorem IsRIntegralRat.mul {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    IsRIntegralRat r (q₁ * q₂)

theorem IsRIntegralRat.sub {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    IsRIntegralRat r (q₁ - q₂)

theorem toZMod_add {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    toZMod (q₁ + q₂) (h₁.add h₂) = toZMod q₁ h₁ + toZMod q₂ h₂

theorem toZMod_mul {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    toZMod (q₁ * q₂) (h₁.mul h₂) = toZMod q₁ h₁ * toZMod q₂ h₂

theorem toZMod_sub {r : ℕ} {q₁ q₂ : ℚ}
    (h₁ : IsRIntegralRat r q₁) (h₂ : IsRIntegralRat r q₂) :
    toZMod (q₁ - q₂) (h₁.sub h₂) = toZMod q₁ h₁ - toZMod q₂ h₂

theorem toZModPS_eq_of_eq {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) (h : F = G) :
    hF.toZModPS = hG.toZModPS

theorem toZModPS_mul {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) :
    (hF.mul hG).toZModPS = hF.toZModPS * hG.toZModPS

theorem toZModPS_sub {r : ℕ} {F G : PowerSeries ℚ}
    (hF : IsRIntegralPS r F) (hG : IsRIntegralPS r G) :
    (hF.sub hG).toZModPS = hF.toZModPS - hG.toZModPS

lemma eq_one_mod_sub_of_pow {A : Type*} [CommRing A] [IsDomain A] {ζ μ : A} {k : ℕ}
    [NeZero k] (hζ : IsPrimitiveRoot ζ k) (hμ : μ ^ k = 1) :
    algebraMap A (A ⧸ Ideal.span ({ζ - 1} : Set A)) μ = 1

theorem conj_map_span_singleton [IsCMField K] (a : 𝓞 K) :
    (Ideal.span {a}).map (ringOfIntegersComplexConj K).toRingEquiv.toRingHom =
      Ideal.span {ringOfIntegersComplexConj K a}

theorem exists_conj_fixed_associate_of_zeta_pow [IsCMField K]
    {hζ : IsPrimitiveRoot (IsCyclotomicExtension.zeta p ℚ K) p}
    (a : 𝓞 K) (u : (𝓞 K)ˣ)
    (hu : ringOfIntegersComplexConj K a = u * a)
    (hclass : ∃ n : ℕ, u = hζ.unit' ^ n) :
    ∃ b : 𝓞 K, ringOfIntegersComplexConj K b = b ∧ Ideal.span {b} = Ideal.span {a}

theorem zpow_pow_eq_self_of_sq_eq_one_of_odd {G : Type*} [CommGroup G] {x : G}
    (hx_sq : x ^ 2 = 1) {n : ℕ} (hn_odd : n % 2 = 1) (s : ℤ) :
    (x ^ s) ^ n = x ^ s

theorem zetaUnit_pow_eq_of_zmod_eq {m n : ℕ}
    (h : (m : ZMod p) = (n : ZMod p)) :
    (zeta_spec p ℚ K).unit' ^ m = (zeta_spec p ℚ K).unit' ^ n

theorem selfInverse_character_image_sq_eq_one {χ : DirichletCharacter ℂ p}
    (hχself : χ = χ⁻¹) :
    (((complexCharacterMulEquivUnits (p := p) χ : (ZMod p)ˣ) : ZMod p) ^ 2) = 1

theorem constOneDirichletCharacterFamily_eq_character {χ : DirichletCharacter ℂ p}
    (hχ : χ ≠ 1) :
    constOneDirichletCharacterFamily (p := p) χ = (χ : ZMod p → ℂ)

theorem inv_mem_nonselfdualCharacterFinset {χ : DirichletCharacter ℂ p}
    (hχ : χ ∈ nonselfdualCharacterFinset (p := p)) :
    χ⁻¹ ∈ nonselfdualCharacterFinset (p := p)

theorem inv_not_mem_nonselfdualCharacterReps {χ : DirichletCharacter ℂ p}
    (hχ : χ ∈ nonselfdualCharacterReps (p := p)) :
    χ⁻¹ ∉ nonselfdualCharacterReps (p := p)

theorem mem_reps_or_inv_mem_reps {hp₂ : p ≠ 2} {χ : DirichletCharacter ℂ p}
    (hχ : χ ∈ nonselfdualCharacterFinset (p := p)) :
    χ ∈ nonselfdualCharacterReps (p := p) ∨ χ⁻¹ ∈ nonselfdualCharacterReps (p := p)

theorem ne_inv_of_mem_nonselfdualCharacterFinset {hp₂ : p ≠ 2} {χ : DirichletCharacter ℂ p}
    (hχ : χ ∈ nonselfdualCharacterFinset (p := p)) :
    χ ≠ χ⁻¹

lemma under_mem_primesOverFinsetPlus {ℓ : ℕ} [Fact ℓ.Prime] {P : Ideal (𝓞 K)}
    (hP : P ∈ primesOverFinset K ℓ) :
    P.under (𝓞 (K⁺)) ∈ primesOverFinsetPlus (K := K) ℓ

theorem dedekindZeta_eq_riemannZeta_mul_nontrivialLProduct_of_one_lt_re {s : ℂ}
    (hs : 1 < s.re) :
    NumberField.dedekindZeta K s = riemannZeta s * nontrivialLProduct p s

theorem inv_mem_oddCharactersWithoutQuadratic {χ : DirichletCharacter ℂ p}
    (hχ : χ ∈ oddCharactersWithoutQuadratic (p := p)) :
    χ⁻¹ ∈ oddCharactersWithoutQuadratic (p := p)

theorem dvd_den_add_inv_of_dvd_num {p : ℕ} (hp : p.Prime) {q : ℚ}
    (hdiv : (p : ℤ) ∣ q.num) :
    p ∣ (q + (1 : ℚ) / p).den

theorem factorization_mul_pred_le_pred {ell n : ℕ}
    (hell : ell.Prime) (hn : n ≠ 0) :
    n.factorization ell * (ell - 1) ≤ n - 1

theorem one_le_sub_pred_mul_factorization {ell n : ℕ}
    (hell : ell.Prime) (hn : n ≠ 0) :
    1 ≤ n - (ell - 1) * n.factorization ell

theorem pred_mul_factorization_add_div_le {ell n : ℕ}
    (hell : ell.Prime) :
    (ell - 1) * n.factorization ell + n / ell ≤ n

theorem succ_le_sub_factorization_mul_pred_of_mul_succ_le_of_le {ell N n d : ℕ}
    (hell : ell.Prime) (hd : ell * (N + 1) ≤ d) (hnd : n ≤ d) :
    N + 1 ≤ d - n.factorization ell * (ell - 1)

theorem succ_le_sub_pred_mul_factorization_of_mul_succ_le {ell N n : ℕ}
    (hell : ell.Prime) (hn : ell * (N + 1) ≤ n) :
    N + 1 ≤ n - (ell - 1) * n.factorization ell
